1	/** A live cell's position as [x, y] grid coordinates. */
2	type Cell = [number, number];
3	
4	/** A cell serialized as an "x,y" string, usable as a Set/Map key. */
5	type CellKey = string;
6	
7	const toKey = ([x, y]: Cell): CellKey => `${x},${y}`;
8	const fromKey = (key: CellKey): Cell => key.split(",").map(Number) as Cell;
9	
10	export function nextGeneration(cells: Cell[]): Cell[] {
11	  const live = new Set(cells.map(toKey));
12	
13	  const neighborCounts = new Map<CellKey, number>();
14	  for (const [x, y] of cells) {
15	    for (let dx = -1; dx <= 1; dx++) {
16	      for (let dy = -1; dy <= 1; dy++) {
17	        if (dx === 0 && dy === 0) continue;
18	        const key = toKey([x + dx, y + dy]);
19	        neighborCounts.set(key, (neighborCounts.get(key) ?? 0) + 1);
20	      }
21	    }
22	  }
23	
24	  const next: Cell[] = [];
25	  for (const [key, count] of neighborCounts) {
26	    if (count === 3 || (count === 2 && live.has(key))) {
27	      next.push(fromKey(key));
28	    }
29	  }
30	  return next;
31	}
